        diff = diff < 0.0f ? diff + 360.0f : diff;
        diff %= 360.0f;
        float rotate = _isMoveRotateClockWise ? (diff > 180.0f ? diff - 360.0f : diff) : (diff > 180.0f ? diff : diff - 360.0f);

        return Mathf.Abs(rotate) / 180.0f;
    }
	private float GetWalkTime() {
		return EntityManager.activeFieldPlayer.DashFlag ? 8f : 16f;
	}
	public enum EntityType
	{
		Chara = 0,
		Poke = 1,
		Obj = 2,
	}
}
